#requires -Version 5.1
[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$ProjectPath = "E:\MY PROJECT FOLDER\medical_website"
$PhaseName = "phase10_production_hardening_dashboard_final"
$CommitMessage = "Harden production workflows and polish dashboards"
$Timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupDirectory = Join-Path $ProjectPath "_backup_${PhaseName}_${Timestamp}"
$PatchPath = Join-Path $env:TEMP "arogya_phase10_${Timestamp}.patch"

function Invoke-CheckedCommand {
    param(
        [Parameter(Mandatory = $true)][string]$CommandPath,
        [Parameter(Mandatory = $true)][string[]]$CommandArguments
    )

    & $CommandPath @CommandArguments
    if ($LASTEXITCODE -ne 0) {
        throw "Command failed with exit code $LASTEXITCODE`: $CommandPath $($CommandArguments -join ' ')"
    }
}

if (-not (Test-Path -LiteralPath $ProjectPath -PathType Container)) {
    throw "Project folder not found: $ProjectPath"
}

Set-Location -LiteralPath $ProjectPath

if (-not (Test-Path -LiteralPath ".git" -PathType Container)) {
    throw "This folder is not the expected Git repository: $ProjectPath"
}

$Git = (Get-Command git.exe -ErrorAction Stop).Source
$Npm = (Get-Command npm.cmd -ErrorAction Stop).Source

$Branch = ((& $Git rev-parse --abbrev-ref HEAD) | Out-String).Trim()
if ($LASTEXITCODE -ne 0) {
    throw "Could not read the current Git branch."
}
if ($Branch -ne "main") {
    throw "Expected branch 'main', but current branch is '$Branch'. Switch to main and rerun."
}

& $Git remote get-url origin *> $null
if ($LASTEXITCODE -ne 0) {
    throw "Git remote 'origin' is not configured."
}

& $Git diff --cached --quiet
if ($LASTEXITCODE -eq 1) {
    throw "Staged changes already exist. Commit or unstage them before running this script so they are not mixed into Phase 10."
}
if ($LASTEXITCODE -gt 1) {
    throw "Could not inspect the Git staging area."
}

