bGljLnBhc3N3b3JkX3Jlc2V0X3JlcXVlc3RzICh0b2tlbl9oYXNoLCBleHBpcmVzX2F0KQord2hlcmUgdXNlZF9hdCBpcyBudWxs
OworCitjcmVhdGUgaW5kZXggaWYgbm90IGV4aXN0cyBpZHhfZW1haWxfdmVyaWZpY2F0aW9uX2FjdGl2ZV90b2tlbgorb24gcHVi
bGljLmVtYWlsX3ZlcmlmaWNhdGlvbl90b2tlbnMgKHRva2VuX2hhc2gsIGV4cGlyZXNfYXQpCit3aGVyZSB1c2VkX2F0IGlzIG51
bGw7CisKK2NyZWF0ZSBpbmRleCBpZiBub3QgZXhpc3RzIGlkeF9hZG1pbl8yZmFfYWN0aXZlX2NoYWxsZW5nZQorb24gcHVibGlj
LmFkbWluXzJmYV9jaGFsbGVuZ2VzIChpZCwgZXhwaXJlc19hdCkKK3doZXJlIHVzZWRfYXQgaXMgbnVsbDsKKworY29tbWl0Owo=
'@ -replace '\s', ''

[System.IO.File]::WriteAllBytes(
    $PatchPath,
    [System.Convert]::FromBase64String($PatchBase64)
)

try {
    $FilesToTouch = @(
        Get-Content -LiteralPath $PatchPath | ForEach-Object {
            if ($_ -match '^\+\+\+ b/(.+)$') {
                $Matches[1]
            }
        } | Sort-Object -Unique
    )

    if ($FilesToTouch.Count -lt 1) {
        throw "The embedded Phase 10 patch is empty or invalid."
    }

    New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
    $ExistingFiles = New-Object System.Collections.Generic.List[string]
    $NewFiles = New-Object System.Collections.Generic.List[string]

    foreach ($RelativePath in $FilesToTouch) {
        $SourcePath = Join-Path $ProjectPath $RelativePath
        if (Test-Path -LiteralPath $SourcePath -PathType Leaf) {
            $DestinationPath = Join-Path $BackupDirectory $RelativePath
            $DestinationFolder = Split-Path -Parent $DestinationPath
            New-Item -ItemType Directory -Path $DestinationFolder -Force | Out-Null
            Copy-Item -LiteralPath $SourcePath -Destination $DestinationPath -Force
            $ExistingFiles.Add($RelativePath)
        }
        else {
            $NewFiles.Add($RelativePath)
        }
    }

    @(
        "Arogya Phase 10 backup"
        "Created: $(Get-Date -Format o)"
        "Project: $ProjectPath"
        ""
        "Existing files backed up:"
        $ExistingFiles
        ""
        "Files that were new in this phase:"
        $NewFiles
        ""
        "Git status before patch:"
        (& $Git status --porcelain=v1)
    ) | Set-Content -LiteralPath (Join-Path $BackupDirectory "BACKUP_MANIFEST.txt") -Encoding UTF8

    Write-Host "Backup created: $BackupDirectory" -ForegroundColor Cyan

    & $Git apply --check --ignore-space-change --whitespace=nowarn -- $PatchPath *> $null
    $ForwardCheck = $LASTEXITCODE

    if ($ForwardCheck -eq 0) {
        Invoke-CheckedCommand $Git @(
            "apply",
            "--ignore-space-change",
            "--whitespace=nowarn",
            "--",
            $PatchPath
        )
        Write-Host "Phase 10 source patch applied." -ForegroundColor Green
    }
    else {
        & $Git apply --reverse --check --ignore-space-change --whitespace=nowarn -- $PatchPath *> $null
        if ($LASTEXITCODE -eq 0) {
            Write-Host "Phase 10 source changes are already present; continuing with verification." -ForegroundColor Yellow
        }
        else {
            throw "The uploaded project has changed in one or more Phase 10 files. Nothing was overwritten. Review the backup and request a refreshed patch for the newer source."
        }
    }

    if (-not (Test-Path -LiteralPath "node_modules" -PathType Container)) {
        Write-Host "Installing locked dependencies because node_modules is missing..." -ForegroundColor Cyan
        Invoke-CheckedCommand $Npm @("ci")
    }

    Write-Host "Running security regression checks..." -ForegroundColor Cyan
    Invoke-CheckedCommand $Npm @("run", "test:security")

    Write-Host "Running TypeScript validation..." -ForegroundColor Cyan
    Invoke-CheckedCommand $Npm @("run", "typecheck")

    Write-Host "Running the full production build..." -ForegroundColor Cyan
    Invoke-CheckedCommand $Npm @("run", "build")

    Write-Host "Checking for high/critical dependency vulnerabilities..." -ForegroundColor Cyan
    Invoke-CheckedCommand $Npm @("audit", "--omit=dev", "--audit-level=high")

    Invoke-CheckedCommand $Git @("diff", "--check")

    $SqlPath = Join-Path $ProjectPath "supabase\PHASE_10_PRODUCTION_HARDENING.sql"
    if (-not (Test-Path -LiteralPath $SqlPath -PathType Leaf)) {
        throw "Required Supabase migration file is missing: $SqlPath"
    }

    try {
        Set-Clipboard -Value (Get-Content -LiteralPath $SqlPath -Raw)
        Write-Host "The Phase 10 SQL has also been copied to your clipboard." -ForegroundColor Green
    }
    catch {
        Write-Warning "Clipboard copy was unavailable. Open the SQL file directly."
    }

    Write-Host ""
    Write-Host "DATABASE STEP REQUIRED BEFORE DEPLOYMENT" -ForegroundColor Yellow
    Write-Host "1. Open Supabase Dashboard -> SQL Editor." -ForegroundColor Yellow
    Write-Host "2. Run this complete file: $SqlPath" -ForegroundColor Yellow
    Write-Host "3. The four diagnostic queries must show no unresolved duplicates." -ForegroundColor Yellow
    Write-Host "4. If index creation succeeds, return here." -ForegroundColor Yellow
    Write-Host ""

    $Confirmation = Read-Host "Type APPLIED only after the Supabase SQL succeeds"
    if ($Confirmation -cne "APPLIED") {
        Write-Warning "Stopped safely before commit and push. Source changes remain in your working tree and the backup is intact. Rerun this script after applying the SQL."
        return
    }

    foreach ($RelativePath in $FilesToTouch) {
        Invoke-CheckedCommand $Git @("add", "--", $RelativePath)
    }

    $StagedFiles = @(& $Git diff --cached --name-only)
    if ($LASTEXITCODE -ne 0) {
        throw "Could not inspect staged Phase 10 files."
    }

    $UnexpectedStagedFiles = @(
        $StagedFiles | Where-Object { $_ -notin $FilesToTouch }
    )
    if ($UnexpectedStagedFiles.Count -gt 0) {
        throw "Unexpected files entered the staging area: $($UnexpectedStagedFiles -join ', ')"
    }

    & $Git diff --cached --quiet
    if ($LASTEXITCODE -eq 0) {
        Write-Host "No new Phase 10 commit was needed; the tested changes are already committed." -ForegroundColor Yellow
    }
    elseif ($LASTEXITCODE -eq 1) {
        Invoke-CheckedCommand $Git @("commit", "-m", $CommitMessage)
    }
    else {
        throw "Could not inspect staged changes before commit."
    }

    Invoke-CheckedCommand $Git @("push", "origin", "main")

    Write-Host ""
    Write-Host "Phase 10 completed successfully." -ForegroundColor Green
    Write-Host "Security checks, typecheck, build, audit threshold, commit, and push all passed." -ForegroundColor Green
    Write-Host "Vercel can now deploy from origin/main. Existing portal sessions must log in once again." -ForegroundColor Cyan
}
finally {
    if (Test-Path -LiteralPath $PatchPath) {
        Remove-Item -LiteralPath $PatchPath -Force -ErrorAction SilentlyContinue
    }
}
